$ErrorActionPreference = 'Stop'

function Get-Prop { param($o, [string]$n) if ($null -eq $o) { return $null }; if ($o -is [System.Collections.IDictionary]) { if ($o.Contains($n)) { return $o[$n] }; return $null }; $p = $o.PSObject.Properties[$n]; if ($p) { return $p.Value }; return $null }
function Read-Json { param($v) if ($null -eq $v) { return $null }; if ($v -isnot [string]) { return $v }; if (-not $v.Trim()) { return $null }; try { return ($v | ConvertFrom-Json) } catch { return $null } }
$stopState = @{ done = $false; ticket = '' }
$warnings = New-Object System.Collections.ArrayList
function Get-AllWarnings {
    param($Own)
    $all = New-Object System.Collections.ArrayList
    foreach ($w in @(@($Own) + @($PsaState.Warnings))) { $t = [string]$w; if ($t -and -not $all.Contains($t)) { $null = $all.Add($t) } }
    return @($all)
}
trap { if (-not $stopState.done) { $stopState.done = $true; Set-NodeOutput ([ordered]@{ status = 'error'; message = [string]$_.Exception.Message; public_note = ''; internal_note = "Priority scoring failed while writing to the PSA: $($_.Exception.Message)"; ticket_id = $stopState.ticket; actions = @(); warnings = @(Get-AllWarnings $warnings) }) }; break }

$ctx = Read-Json (Get-NodeInput -Name 'ctx')
if ($null -eq $ctx) { $stopState.done = $true; Set-NodeOutput ([ordered]@{ status = 'error'; message = 'The score from the first step is missing. Run the workflow from the start.'; public_note = ''; internal_note = ''; ticket_id = ''; actions = @(); warnings = @() }); throw 'The score from the first step is missing.' }
$id = [string]$ctx.ticketId; $num = [string]$ctx.number; $stopState.ticket = $num
$actions = New-Object System.Collections.ArrayList; foreach ($a in @($ctx.actions)) { if ($a) { $null = $actions.Add([string]$a) } }
foreach ($w in @($ctx.warnings)) { if ($w) { $null = $warnings.Add([string]$w) } }
$counts = [ordered]@{ prioritySet = 0; dispatcherEmailed = 0; notesWritten = 0 }

# The breakdown a technician reads.
$lines = @("Priority score for ticket $($num): $($ctx.score) of 100, which is $($ctx.scored).")
foreach ($pt in @($ctx.parts)) { $lines += " $(if ([int]$pt.points -ge 0) { '+' })$($pt.points) $($pt.why)" }
$lines += "Thresholds: 70 critical, 45 high, 25 medium. Automatic priority stops at high."
$lines += [string]$ctx.why
if ($ctx.flagP1) { $lines += 'POSSIBLE P1: this looks critical. A person should decide whether to raise it to critical.' }

function Complete-Run {
    param([string]$Status, [string]$Message, [string]$Internal)
    $stopState.done = $true
    Set-NodeOutput ([ordered]@{
            status = $Status; message = $Message; public_note = ''; internal_note = $Internal; ticket_id = $num
            score = [int]$ctx.score; level = [string]$ctx.scored; priority_from = [string]$ctx.currentLabel; possible_p1 = [bool]$ctx.flagP1
            counts = $counts; actions = @($actions); warnings = @(Get-AllWarnings $warnings)
        })
}

if (-not $ctx.confirm) {
    $plan = @()
    if ($ctx.change) { $plan += "set the priority to $($ctx.target)" }
    if ($ctx.flagP1) { $plan += 'email the dispatcher about a possible P1' }
    if ($ctx.addNote) { $plan += 'add the score as an internal note' }
    $msg = "Preview only, nothing was changed. Ticket $num scored $($ctx.score) ($($ctx.scored)). $(if ($plan.Count) { 'Would ' + ($plan -join ', ') + '.' } else { 'Nothing to do.' })"
    Complete-Run 'pending_confirmation' $msg ($lines -join "`n")
    return
}

$conn = Connect-Psa -Psa ([string]$ctx.psa)
$psaName = Get-PsaName
# A run that already noted this ticket changes nothing again, so the dispatcher is never emailed twice.
$notes = @()
try { $notes = @(Get-PsaTicketNotes -Id $id -Newest -TextOnly) } catch { $null = $warnings.Add("The ticket's notes couldn't be read, so nothing was changed in case it was already scored: $($_.Exception.Message)"); Complete-Run 'incomplete' "Ticket $num wasn't changed: its notes couldn't be read." ($lines -join "`n"); return }
if (Test-PsaNoteMarker -Id $id -Marker 'priority-scoring' -Notes @($notes | Where-Object { $_.internal })) {
    Complete-Run 'success' "Ticket $num was already scored, so nothing was changed again." ''
    return
}

if ($ctx.change) {
    try { $label = Set-PsaPriority -Id $id -Level ([string]$ctx.target); $counts.prioritySet = 1; $null = $actions.Add("Set ticket $num to $label ($($ctx.target)).") }
    catch { $null = $warnings.Add("$psaName didn't accept the new priority, so it was left as it is: $($_.Exception.Message)"); $lines += "The priority couldn't be set: $($_.Exception.Message)" }
}
if ($ctx.flagP1) {
    $to = $(if ($ctx.dispatcher) { [string]$ctx.dispatcher } else { [string](Get-PsaSecret 'Dispatcher-Email') })
    $subject = "Possible P1: ticket $num for $($ctx.company)"
    $text = "Ticket $num for $($ctx.company) scored $($ctx.score) of 100 and may be critical.`n`nSummary: $($ctx.summary)`n$(if ($ctx.url) { "Link: $($ctx.url)`n" })`nWhy:`n$((@($ctx.parts) | ForEach-Object { " - $($_.why)" }) -join "`n")`n`nThe workflow raised it no higher than high. Please decide whether it should be critical."
    $r = $(if ($to) { Send-PmMail -To $to -Subject $subject -Text $text -Tag 'priority-scoring' } else { @{ sent = $false; reason = 'No dispatcher address is set (dispatcher_email input or Dispatcher-Email secret).' } })
    if ($r.sent) { $counts.dispatcherEmailed = 1; $null = $actions.Add("Emailed the dispatcher ($to) about a possible P1.") }
    else { $lines += "The dispatcher wasn't emailed: $($r.reason) Check this ticket now."; $null = $warnings.Add("The dispatcher wasn't emailed about a possible P1: $($r.reason)") }
}
$internal = $lines -join "`n"
if ($ctx.addNote -or $ctx.flagP1) {
    try {
        $res = Add-PsaNote -Id $id -Text $internal -Title 'Priority score' -Internal -Marker 'priority-scoring'
        if ($res -eq 'written') { $counts.notesWritten = 1; $null = $actions.Add("Added the score as an internal note on ticket $num.") }
    }
    catch { $null = $warnings.Add("The score note couldn't be added to ticket $($num): $($_.Exception.Message)") }
}
$msg = "Ticket $num scored $($ctx.score) ($($ctx.scored)). $(if ($counts.prioritySet) { "Raised it to $($ctx.target)." } else { [string]$ctx.why })$(if ($ctx.flagP1) { if ($counts.dispatcherEmailed) { ' The dispatcher was emailed about a possible P1.' } else { ' Possible P1: the dispatcher was NOT emailed.' } })"
Complete-Run $(if ($ctx.flagP1 -and -not $counts.dispatcherEmailed) { 'incomplete' } else { 'success' }) $msg $internal
